SELECT cs.cs_sold_date_sk, cs.cs_quantity, cs.cs_wholesale_cost, cs.cs_list_price, cs.cs_quantity * cs.cs_wholesale_cost AS wholesale_total, cs.cs_quantity * cs.cs_list_price AS list_total, CASE WHEN cs.cs_quantity > 59 THEN cs.cs_quantity * cs.cs_wholesale_cost ELSE cs.cs_quantity * cs.cs_list_price END AS price_based_on_quantity, sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, (cs.cs_ext_sales_price - cs.cs_ext_discount_amt) * 1.1 AS adjusted_sales_price FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_sold_date_sk = 2450855 AND sm.sm_type = 'REGULAR                       '
